import{_ as t,o as a,c as o,ag as d}from"./chunks/framework.HG0H2VLS.js";const p=JSON.parse('{"title":"FullBadge — Figma Notes","description":"","frontmatter":{},"headers":[],"relativePath":"public/demos/src/components/FullBadge/FullBadge.figma-notes.md","filePath":"public/demos/src/components/FullBadge/FullBadge.figma-notes.md"}'),i={name:"public/demos/src/components/FullBadge/FullBadge.figma-notes.md"};function s(n,e,r,c,h,l){return a(),o("div",null,[...e[0]||(e[0]=[d(`<h1 id="fullbadge-—-figma-notes" tabindex="-1">FullBadge — Figma Notes <a class="header-anchor" href="#fullbadge-—-figma-notes" aria-label="Permalink to &quot;FullBadge — Figma Notes&quot;">​</a></h1><p><strong>Tier:</strong> Component <strong>Built:</strong> 2026-08-25 (extracted during Seating Planner wave 3) <strong>Files:</strong> <code>FullBadge.css</code>, <code>FullBadge.html</code>, <code>FullBadge.figma.ts</code>, <code>FullBadge.figma-notes.md</code><strong>Consumed by:</strong> RoomCard, TableCard <strong>JS:</strong> none</p><h2 id="it-is-a-real-figma-component-now-2026-09-11" tabindex="-1">It is a real Figma component now (2026-09-11) <a class="header-anchor" href="#it-is-a-real-figma-component-now-2026-09-11" aria-label="Permalink to &quot;It is a real Figma component now (2026-09-11)&quot;">​</a></h2><p>It was not, for the first two and a half weeks of its life — the section this replaces existed to warn that FullBadge had been <strong>extracted from code</strong>, and that Figma drew it as four hand-drawn <code>Full-Badge</code> frames across RoomCard and TableCard rather than one component with four instances. The designer has now promoted it, which closes all three consequences that note listed.</p><h3 id="figma-node" tabindex="-1">Figma node <a class="header-anchor" href="#figma-node" aria-label="Permalink to &quot;Figma node&quot;">​</a></h3><ul><li><strong>File key:</strong> <code>Lus07xi8pPXLN87sQIyrEt</code></li><li><strong>Component set:</strong> <code>3615:110610</code> — <a href="https://www.figma.com/design/Lus07xi8pPXLN87sQIyrEt/Affino---Design-System?node-id=3615-110610" target="_blank" rel="noreferrer">Full-Badge</a></li></ul><h3 id="variant-matrix-1-variant" tabindex="-1">Variant matrix (1 variant) <a class="header-anchor" href="#variant-matrix-1-variant" aria-label="Permalink to &quot;Variant matrix (1 variant)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Node ID</th><th>Variant</th><th>Size</th><th>Notes</th></tr></thead><tbody><tr><td><code>3615:110609</code></td><td><code>Tier=Component</code></td><td>45×15</td><td>the only variant</td></tr></tbody></table><p><code>Tier</code> is single-valued and produces no CSS, so <strong>there are no modifiers</strong> — the same shape as TableType, RoomCard and TableCard in this module. There is also <strong>no TEXT property</strong>: &quot;Full&quot; is a static text layer (<code>3615:110607</code>), so the label is fixed in markup rather than mapped with <code>figma.string</code>. If the badge ever needs other words, that has to become a Figma property first.</p><h3 id="code-connect-is-live" tabindex="-1">Code Connect is live <a class="header-anchor" href="#code-connect-is-live" aria-label="Permalink to &quot;Code Connect is live&quot;">​</a></h3><p><code>FullBadge.figma.ts</code> exists as of this build — it could not before, because <code>figma.connect</code> needs a component to attach to and a frame-targeted mapping would have been worse than none. Parses clean against all 75 files.</p><h3 id="the-audit-found-two-mismatches" tabindex="-1">The audit found two mismatches <a class="header-anchor" href="#the-audit-found-two-mismatches" aria-label="Permalink to &quot;The audit found two mismatches&quot;">​</a></h3><p>Both were real, and both compound in the same direction: the badge rendered about <strong>49px wide against Figma&#39;s 45</strong>.</p><table tabindex="0"><thead><tr><th>Property</th><th>Figma <code>3615:110609</code></th><th>Code was</th><th>Resolution</th></tr></thead><tbody><tr><td>gap</td><td><code>border/width/border-3</code> = 3px</td><td><code>--ai-spacing-1</code> = 4px</td><td><strong>Figma binding fixed</strong> — see below</td></tr><tr><td>check icon</td><td>7px</td><td>10px, hardcoded</td><td><strong>new token</strong> — see below</td></tr></tbody></table><p>Everything else matched exactly: <code>--ai-surface-success</code>, <code>--ai-spacing-2</code> inline, <code>--ai-spacing-0-5</code> block, <code>--ai-radius-full</code>, and the full type stack (<code>--ai-font-title</code> / <code>--ai-font-bold</code> / <code>--ai-font-fixed-6xs</code> / <code>--ai-text-invert</code> / uppercase / <code>leading: normal</code>). <code>--ai-surface-success</code> is <code>#30a46c</code> in <strong>all three modes</strong> — light, dark and CC — so the green is theme-invariant and matches Figma&#39;s value precisely.</p><h4 id="the-gap-was-a-figma-side-binding-slip" tabindex="-1">The gap was a Figma-side binding slip <a class="header-anchor" href="#the-gap-was-a-figma-side-binding-slip" aria-label="Permalink to &quot;The gap was a Figma-side binding slip&quot;">​</a></h4><p>Figma bound <strong><code>border/width/border-3</code></strong> — a <em>border-width</em> primitive — as the flex gap. A border width driving spacing is semantically wrong, and it is why the code deviated to <code>--ai-spacing-1</code> in the first place. Designer&#39;s call (2026-09-11): <strong>fix the binding in Figma</strong> to <code>--ai-spacing-1</code> rather than propagate 3px into code. <strong>No code change</strong> — the CSS was already right, and it is the source that moves.</p><h4 id="the-icon-is-now-7px-as-an-explicitly-approved-raw-value" tabindex="-1">The icon is now 7px, as an explicitly approved raw value <a class="header-anchor" href="#the-icon-is-now-7px-as-an-explicitly-approved-raw-value" aria-label="Permalink to &quot;The icon is now 7px, as an explicitly approved raw value&quot;">​</a></h4><p>Figma draws the check at <strong>7px</strong>. Nothing on the <code>--ai-*</code> scale is 7px, and the smallest icon token (<code>--ai-icon-size-xs</code>) is 12px, which will not sit inside a 15px badge. The code meanwhile carried a <strong>hardcoded 10px</strong>, which was a governance violation predating this audit.</p><p>The first decision (2026-09-11) was to add an <code>--ai-icon-size-2xs</code> token. That was then <strong>revised the same day</strong>: the designer approved a <strong>raw 7px</strong> instead, on the grounds that it is a single use. That is a legitimate resolution of the hardcoded-dimension rule — the rule&#39;s own remedies are &quot;add a token / approve a <code>calc()</code> / <strong>approve as a primitive</strong>&quot;, and the stop exists to force the question, not to forbid the answer. Recorded here rather than left as an unexplained literal, because an <em>unrecorded</em> one-off is exactly how hardcoded dimensions accumulate.</p><div class="language-css vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">css</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">inline-size</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 7px;     </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* Figma 3615:110605 — approved raw, designer 2026-09-11 */</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">stroke-width</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: 5.7px;  </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">/* was 4 — see below, these are a pair */</span></span></code></pre></div><p>If a second component ever needs 7px, that is the signal to promote it to a token rather than copy the literal.</p><h4 id="the-stroke-had-to-go-4-→-5-7-or-the-resize-would-have-undone-the-2026-08-25-fix" tabindex="-1">The stroke HAD to go 4 → 5.7, or the resize would have undone the 2026-08-25 fix <a class="header-anchor" href="#the-stroke-had-to-go-4-→-5-7-or-the-resize-would-have-undone-the-2026-08-25-fix" aria-label="Permalink to &quot;The stroke HAD to go 4 → 5.7, or the resize would have undone the 2026-08-25 fix&quot;">​</a></h4><p>This nearly went wrong, and it is the reason the two values are a pair. The 10px was <strong>not</strong> sloppiness — it was a deliberate legibility decision (see <em>Two places the CSS leads Figma</em>): Lucide draws on a 24-unit viewBox, so the stroke thins in proportion to the rendered size, and at 7px the default all but vanished against the green. Shrinking the icon without touching the stroke would have quietly reintroduced exactly that, on a badge whose contrast <strong>already fails AA at 3.16:1</strong>.</p><p>Rendered stroke is <code>stroke-width × size ÷ 24</code>. Measured at true 1×, because a scaled vector preview hides this — the same method the original decision was verified with:</p><table tabindex="0"><thead><tr><th>Size</th><th><code>stroke-width</code></th><th>Rendered stroke</th></tr></thead><tbody><tr><td>10px (old)</td><td>4</td><td>1.67px</td></tr><tr><td>7px</td><td>4</td><td><strong>1.17px</strong> ← the hairline</td></tr><tr><td>7px</td><td>5</td><td>1.46px</td></tr><tr><td><strong>7px (now)</strong></td><td><strong>5.7</strong></td><td><strong>1.66px</strong> ← matches the old weight</td></tr><tr><td>7px</td><td>7</td><td>2.04px</td></tr></tbody></table><p>So the check got <strong>smaller, not thinner</strong>. Applying either value alone is a regression in one direction or the other. <code>stroke-width</code> stays raw by the same reasoning as border widths — it is an optical unit, the SVG analogue of a border, and the <code>4px</code> it replaces was already documented so.</p><h4 id="where-that-leaves-the-measurements" tabindex="-1">Where that leaves the measurements <a class="header-anchor" href="#where-that-leaves-the-measurements" aria-label="Permalink to &quot;Where that leaves the measurements&quot;">​</a></h4><p>Measured on the component&#39;s own demo, with Inter actually loaded:</p><table tabindex="0"><thead><tr><th></th><th>Figma</th><th>Code</th></tr></thead><tbody><tr><td>badge</td><td>45 × 15</td><td><strong>46.9 × 15</strong></td></tr><tr><td>icon</td><td>7</td><td><strong>7</strong></td></tr><tr><td>rendered stroke</td><td>—</td><td><strong>1.66px</strong></td></tr></tbody></table><p>Height is now exact. The badge was <strong>49.9</strong> wide before this change, so the icon accounts for the full 3px improvement. The residual ~1.9px is entirely the two documented <em>CSS-leads-Figma</em> items: the gap is 4px against Figma&#39;s 3px (and Figma is being corrected to 4, which closes 1px of it), and <code>--ai-tracking-7</code> adds letter-spacing Figma does not set. Once the gap binding lands, Figma reads 46 and code 46.9.</p><blockquote><p><strong>Beware measuring this in a bare probe.</strong> A minimal test page without the real font stack reported the badge as 14px tall rather than 15 — the fallback font&#39;s <code>normal</code> line-height at 9px is a pixel shorter than Inter&#39;s, and the text box is what drives the height, not the icon. Measure on the demo page.</p></blockquote><h3 id="also-worth-knowing-the-figma-file-has-been-renamed" tabindex="-1">Also worth knowing: the Figma file has been renamed <a class="header-anchor" href="#also-worth-knowing-the-figma-file-has-been-renamed" aria-label="Permalink to &quot;Also worth knowing: the Figma file has been renamed&quot;">​</a></h3><p>The URL the designer supplied reads <code>Affino---Design-System</code>, where every existing <code>.figma.ts</code> in this repo carries the older <code>Affino-AI---Design-System</code> slug. Code Connect matches on the <strong>file key</strong>, not the slug, so all 85 existing mappings still resolve and nothing is broken — but they now carry a stale name. This file uses the current slug. Worth a sweep if the inconsistency ever grates.</p><h2 id="why-it-was-extracted" tabindex="-1">Why it was extracted <a class="header-anchor" href="#why-it-was-extracted" aria-label="Permalink to &quot;Why it was extracted&quot;">​</a></h2><p>It was originally scoped inside RoomCard as <code>.room-card__badge</code> (2026-08-25). When TableCard turned out to draw an identical copy, the designer chose extraction over duplicating it — so the open contrast question below and the check-icon sizing live in one file rather than two.</p><h2 id="token-mapping" tabindex="-1">Token mapping <a class="header-anchor" href="#token-mapping" aria-label="Permalink to &quot;Token mapping&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Figma</th><th>CSS</th><th>Role</th></tr></thead><tbody><tr><td><code>--ai-surface-success</code></td><td><code>background-color</code></td><td></td></tr><tr><td><code>--ai-text-invert</code></td><td><code>color</code></td><td>was the <code>Grey/0</code> primitive in Figma</td></tr><tr><td><code>--ai-radius-full</code></td><td><code>border-radius</code></td><td></td></tr><tr><td><code>--ai-spacing-2</code></td><td><code>padding-inline</code> (6px)</td><td></td></tr><tr><td><code>--ai-spacing-0-5</code></td><td><code>padding-block</code> (2px)</td><td></td></tr><tr><td><code>--ai-spacing-1</code></td><td><code>gap</code> (4px)</td><td>Figma bound <code>border/width/border-3</code> — see below</td></tr><tr><td><code>--ai-font-title</code></td><td><code>font-family</code></td><td></td></tr><tr><td><code>--ai-font-fixed-6xs</code></td><td><code>font-size</code> (9px)</td><td>the token added 2026-08-25</td></tr><tr><td><code>--ai-font-bold</code></td><td><code>font-weight</code></td><td></td></tr><tr><td><code>--ai-tracking-7</code></td><td><code>letter-spacing</code></td><td>CSS leads Figma — see below</td></tr></tbody></table><h2 id="token-gaps-and-decisions" tabindex="-1">Token gaps and decisions <a class="header-anchor" href="#token-gaps-and-decisions" aria-label="Permalink to &quot;Token gaps and decisions&quot;">​</a></h2><p>Resolved with the designer 2026-08-25 rather than invented.</p><table tabindex="0"><thead><tr><th>Figma</th><th>Decision</th></tr></thead><tbody><tr><td><code>gap</code> bound to <code>border/width/border-3</code> (3px)</td><td><strong><code>--ai-spacing-1</code></strong> (4px). A border-width token driving a flex gap, and 3px matches no spacing step. Figma updated.</td></tr><tr><td>label <code>9px</code>, unbound</td><td><strong>New token <code>--ai-font-fixed-6xs</code></strong>, created in Figma and re-exported the same day.</td></tr><tr><td><code>Grey/0</code> primitive (<code>#ffffff</code>)</td><td><strong><code>--ai-text-invert</code></strong>, which is exactly <code>#ffffff</code>.</td></tr><tr><td>check icon <code>7×7</code></td><td><strong>Raw 7×7 + <code>stroke-width: 5.7</code>, designer-approved 2026-09-11.</strong> Was a raw 10×10; no icon token fits, the smallest (<code>--ai-icon-size-xs</code>) being 12px. A token (<code>--ai-icon-size-2xs</code>) was briefly agreed and then revised the same day to an approved raw value, on the grounds of a single use. The stroke change is not optional — see the component section above.</td></tr></tbody></table><h2 id="two-places-the-css-leads-figma" tabindex="-1">Two places the CSS leads Figma <a class="header-anchor" href="#two-places-the-css-leads-figma" aria-label="Permalink to &quot;Two places the CSS leads Figma&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Property</th><th>Figma</th><th>CSS</th></tr></thead><tbody><tr><td>check icon</td><td><code>7×7</code>, default stroke</td><td><code>7×7</code>, <strong><code>stroke-width: 5.7</code></strong> — size now MATCHES Figma (2026-09-11); only the stroke leads</td></tr><tr><td>label <code>letter-spacing</code></td><td><strong>not set</strong></td><td><strong><code>--ai-tracking-7</code></strong> (0.05em)</td></tr></tbody></table><p><strong>The check had to grow to stay legible.</strong> Lucide renders on a 24-unit viewBox, so its default <code>stroke-width: 2</code> thins to roughly 0.6px once scaled to 7px — a hairline that all but disappeared against the green. 10px with <code>stroke-width: 4</code> reads properly. Verified against a true 1× raster upscaled with nearest-neighbour, not a scaled vector preview, because scaling hides exactly that thinning. CSS <code>stroke-width</code> beats the <code>stroke-width=&quot;2&quot;</code> presentation attribute Lucide writes onto the <code>&lt;svg&gt;</code>; both <code>[data-lucide]</code> and <code>svg</code> are targeted because <code>createIcons()</code> swaps the element.</p><p><strong>The tracking is an addition</strong> — 9px bold uppercase sets very tight, and it matches the treatment TableType&#39;s uppercase micro-label was given.</p><p><strong>Superseded 2026-09-11.</strong> The icon now matches Figma at 7px, so only the stroke and the tracking lead. The badge renders <strong>46.9×15 against Figma&#39;s 45×15</strong> — height exact, and the residual width is the 1px gap difference (Figma being corrected to 4px) plus the letter-spacing Figma does not set.</p><h2 id="accessibility-—-one-open-item" tabindex="-1">Accessibility — one open item <a class="header-anchor" href="#accessibility-—-one-open-item" aria-label="Permalink to &quot;Accessibility — one open item&quot;">​</a></h2><p><strong>White on <code>--ai-surface-success</code> measures 3.16:1</strong>, under the 4.5:1 WCAG AA requires for 9px bold text. It needs either a darker success or a dark label — a palette decision, not something this component can fix. <strong>Deliberately left open</strong> at the designer&#39;s direction 2026-08-25; tracked with the other unresolved pairs in <code>docs/contrast-audit.md</code>.</p><p>Fixing it here now fixes it for both consumers at once, which is part of why extraction was worth doing.</p><h2 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h2><ul><li><strong>Ships as a <code>&lt;span&gt;</code>.</strong> It was a <code>&lt;p&gt;</code> while scoped inside RoomCard, which needed a <code>margin: 0</code> reset — the reset is kept defensively, since a caller reaching for a block element would otherwise inherit margins and push its row out of alignment. That bug did occur once, adding 16px to RoomCard&#39;s Full card only.</li><li><strong><code>flex-shrink: 0</code></strong> because it always shares a flex row with a growing text node.</li><li>The Lucide name is <code>check</code>, matching Figma&#39;s <code>CheckIcon</code> / <code>check</code> layer names.</li></ul>`,51)])])}const m=t(i,[["render",s]]);export{p as __pageData,m as default};
